<script>(function(){var form=document.getElementById('patron-feedback-form'),note=document.getElementById('type-note'),rating=document.getElementById('rating-field'),collection=document.getElementById('collection-fields'),locationField=document.getElementById('location-field'),subject=document.getElementById('subject-label'),message=document.getElementById('message-label');if(!form)return;var copy={service_review:{note:'Ceritakan pengalaman Anda saat menggunakan layanan. Nilai bintang membantu kami mengukur kualitas layanan.',subject:'Judul ulasan',message:'Pengalaman Anda'},book_request:{note:'Sebutkan buku yang Anda harapkan. Isi penulis, ISBN, atau format bila informasinya diketahui.',subject:'Judul buku yang diusulkan',message:'Alasan buku ini diperlukan'},digital_content:{note:'Usulkan ebook, video, audio, modul, atau sumber belajar digital yang bermanfaat.',subject:'Judul atau jenis konten digital',message:'Kebutuhan dan manfaat konten'},facility:{note:'Sampaikan kebutuhan ruang baca, koleksi fisik, jaringan, komputer, atau pojok baca tertentu.',subject:'Judul saran fasilitas',message:'Kebutuhan atau kondisi yang ditemui'},feature:{note:'Ceritakan fitur aplikasi yang akan membuat layanan digital lebih mudah digunakan.',subject:'Judul usul fitur',message:'Masalah yang ingin diselesaikan dan usulan Anda'},complaint:{note:'Keluhan akan ditangani secara tertutup. Cantumkan lokasi atau halaman layanan agar petugas dapat menelusuri masalahnya.',subject:'Ringkasan keluhan',message:'Kronologi atau masalah yang dialami'},other:{note:'Gunakan ruang ini untuk pesan yang belum tercakup pada pilihan lain.',subject:'Judul pesan',message:'Isi pesan'}};function toggle(el,show){el.hidden=!show;el.querySelectorAll('input,select,textarea').forEach(function(f){f.disabled=!show;});}function update(){var selected=form.querySelector('[name="feedback_type"]:checked'),type=selected?selected.value:'';if(!type){note.style.display='none';return;}var item=copy[type];note.textContent=item.note;note.style.display='block';subject.textContent=item.subject;message.textContent=item.message;toggle(rating,type==='service_review');toggle(collection,type==='book_request'||type==='digital_content');toggle(locationField,['service_review','facility','complaint'].indexOf(type)!==-1);}form.querySelectorAll('[name="feedback_type"]').forEach(function(r){r.addEventListener('change',update);});update();})();</script></body></html>
